// Package api holds the HTTP API contract, generated by `make openapi`. Don't edit openapi.json by
// hand: it comes from the annotations on the handlers.
package api

import _ "embed"

// OpenAPISpec is the OpenAPI document describing every HTTP route. It is embedded so the server
// can serve it wherever it runs, without depending on the working directory.
//
//go:embed openapi.json
var OpenAPISpec []byte
